import{_ as t}from"./chunks/run-timeline.Dzomeifv.js";import{_ as a}from"./chunks/performance-trends.BEEamWXJ.js";import{_ as s,o as i,c as o,ak as r}from"./chunks/framework.sV-XtlWr.js";const w=JSON.parse('{"title":"Cut the time the suite costs","description":"","frontmatter":{"title":"Cut the time the suite costs","lang":"en-US"},"headers":[],"relativePath":"recipes/faster-suite.md","filePath":"recipes/faster-suite.md","lastUpdated":1788434302000}'),n={name:"recipes/faster-suite.md"};function l(h,e,u,d,p,c){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="our-suite-takes-too-long-—-where-is-the-time-actually-going" tabindex="-1">Our suite takes too long — where is the time actually going? <a class="header-anchor" href="#our-suite-takes-too-long-—-where-is-the-time-actually-going" aria-label="Permalink to &quot;Our suite takes too long — where is the time actually going?&quot;">​</a></h1><p>The instinct is to look for slow tests. That is usually the smallest part of the bill. A suite&#39;s wall clock is mostly made of four things, and only one of them is &quot;the app is slow&quot;:</p><ol><li><strong>Waits somebody wrote</strong> — <code>waitForTimeout</code> sleeps that were a workaround once.</li><li><strong>Timeouts nobody revisited</strong> — a 30s budget on a test that takes 3s costs 27s <em>every time it fails</em>.</li><li><strong>Retries of flaky tests</strong> — paid on every run, and they buy no signal.</li><li><strong>The application itself</strong> — the only part that needs a real fix.</li></ol><p>Piwi measures all four separately, so you can spend effort where the minutes are. It does not make your app faster; it tells you whether that is even the problem.</p><h2 id="_1-split-the-bill-before-optimizing-anything" tabindex="-1">1. Split the bill before optimizing anything <a class="header-anchor" href="#_1-split-the-bill-before-optimizing-anything" aria-label="Permalink to &quot;1. Split the bill before optimizing anything&quot;">​</a></h2><p><a href="./../analytics.html">Analytics</a> has two widgets that belong side by side: <strong>CI time</strong> (total minutes your runs consumed) and <strong>Wasted CI time</strong> — the portion that produced no signal, defined as time inside wait steps plus time spent on attempts that ended failed or timed out.</p><p>If wasted time is a small slice, your suite is honestly just big, and steps 2–4 will disappoint you — the application itself and more parallelism (steps 5 and 6) are where to look. If it is a large slice, the next three steps are where your afternoon goes.</p><p>The widget also states how much is <strong>reclaimable</strong> by tightening timeouts and dropping stale <code>test.slow()</code> marks, which is the one number worth quoting to whoever asks why CI is expensive.</p><h2 id="_2-reclaim-the-waits-you-wrote" tabindex="-1">2. Reclaim the waits you wrote <a class="header-anchor" href="#_2-reclaim-the-waits-you-wrote" aria-label="Permalink to &quot;2. Reclaim the waits you wrote&quot;">​</a></h2><p>Piwi classifies wait steps as <strong>wasted time</strong> and totals them per execution and per run. By default only explicit sleeps count — <code>waitForTimeout</code> and friends — because framework-injected waits (load-state, wait-for-function) are usually unavoidable and would drown the signal.</p><ul><li>A failing execution&#39;s summary shows the wasted time spent in fixed waits, right next to its duration.</li><li>A run&#39;s <strong>Timeline</strong> tab draws a per-worker timeline with a <strong>span-type filter</strong> — setup, actual test, wasted waits, teardown. Filter to wasted waits and the sleeps light up as bars you can click straight through to the test.</li><li>Tune what counts in <strong>Settings → Performance</strong> (or lock it with <a href="./../configuration.html#wasted-time"><code>PIWI_WASTED_WAIT_PATTERNS</code></a>). Classification happens <em>when a run is viewed</em>, so widening the patterns re-classifies your whole history immediately — no re-run needed.</li></ul><figure><img src="'+t+'" alt="A run&#39;s Timeline tab: one horizontal lane per worker, tests as bars, with the fixed-wait sleeps highlighted as wasted-wait spans and a span-type filter above"><figcaption>The Timeline tab — one lane per worker, with the fixed-wait sleeps highlighted as their own span so idle time and slow fixtures are obvious.</figcaption></figure><p>Set the patterns to <code>*</code> once, look at the damage, then set them back. It is a fast way to see how much of the suite is waiting on something.</p><h2 id="_3-tighten-the-timeouts-that-only-bill-you-on-failure" tabindex="-1">3. Tighten the timeouts that only bill you on failure <a class="header-anchor" href="#_3-tighten-the-timeouts-that-only-bill-you-on-failure" aria-label="Permalink to &quot;3. Tighten the timeouts that only bill you on failure&quot;">​</a></h2><p>An oversized per-test timeout is free while tests pass and brutal when they don&#39;t: a hung test burns its entire budget before anyone learns anything.</p><p>The <strong>Performance</strong> tab&#39;s <strong>Timeout opportunities</strong> lists tests whose configured timeout dwarfs their real p95 duration, plus tests still carrying a <code>test.slow()</code> mark they have outgrown. Each row suggests a tighter value and the time reclaimable per failing run, ranked by impact.</p><figure><img src="'+a+'" alt="Project Performance tab showing the duration trend chart with total, average and P90 series and timeline markers, above the slowest-tests table"><figcaption>The Performance tab — average and P90 duration over time (with your timeline markers overlaid), then the ranked slowest tests.</figcaption></figure><p>Read the <strong>P90</strong> line, not the average: a handful of slow outliers move P90 and barely move the mean, and it&#39;s the outliers that decide how long a shard takes.</p><h2 id="_4-stop-paying-for-flaky-retries" tabindex="-1">4. Stop paying for flaky retries <a class="header-anchor" href="#_4-stop-paying-for-flaky-retries" aria-label="Permalink to &quot;4. Stop paying for flaky retries&quot;">​</a></h2><p>A flaky test bills you twice — once for the failed attempt, once for the retry — on every run where it misbehaves. That is why Piwi ranks flaky tests by <strong>wasted CI minutes</strong> rather than by flakiness score: a test that flakes constantly but finishes in 200ms costs nothing, and one that flakes weekly on a four-minute timeout is what actually hurts.</p><p><a href="./flaky-cleanup.html">Cutting the flakiness that costs the most</a> is the whole recipe for this. The short version: sort by impact, fix the red dots, and <a href="./../flaky-tests.html#quarantine-with-a-way-out">quarantine</a> the rest so they stop blocking merges while still running.</p><h2 id="_5-ask-whether-the-app-is-slow-not-the-test" tabindex="-1">5. Ask whether the app is slow, not the test <a class="header-anchor" href="#_5-ask-whether-the-app-is-slow-not-the-test" aria-label="Permalink to &quot;5. Ask whether the app is slow, not the test&quot;">​</a></h2><p>Everything above shaves time off the harness. This step is the one that finds a real performance bug.</p><ul><li><strong>Slow endpoints</strong> — on a run, network requests grouped by method and normalized route (<code>/api/users/:id</code>) with avg/p90/max duration and error rate. <a href="./../analytics.html">Analytics</a> lifts the same view across every project, so a shared endpoint regressing shows up before any single suite notices.</li><li><strong>Web Vitals</strong> — TTFB, FCP, LCP, CLS and the rest per execution, color-coded. LCP/CLS/INP are Chromium-only, and INP needs an interaction, so short tests often show <code>n/a</code>.</li></ul><p>Both require the <a href="./../capture-fixtures.html">capture fixtures</a> — the reporter alone cannot see the network. Without them you still have the trace: its network waterfall shows the same requests for one execution, just not aggregated across the suite.</p><h2 id="_6-spend-the-parallelism-you-already-have" tabindex="-1">6. Spend the parallelism you already have <a class="header-anchor" href="#_6-spend-the-parallelism-you-already-have" aria-label="Permalink to &quot;6. Spend the parallelism you already have&quot;">​</a></h2><ul><li><strong>Worker imbalance</strong> is called out in a run&#39;s <a href="./../flaky-tests.html#run-insights">Insights</a>: if one worker finishes long after the others, the suite is as slow as its unluckiest shard, and no amount of per-test tuning fixes that.</li><li><strong>Sharding</strong> is Playwright&#39;s own <code>--shard</code>; Piwi merges the shards back into <a href="./../concepts.html#test-run">one run</a>, so you can raise the shard count without turning your history into fragments. See <a href="./../ci.html#sharding">CI &amp; sharding</a>.</li></ul><h2 id="other-ways-in" tabindex="-1">Other ways in <a class="header-anchor" href="#other-ways-in" aria-label="Permalink to &quot;Other ways in&quot;">​</a></h2><p><strong>Ask your agent.</strong> Over the <a href="./../mcp.html">MCP server</a> — no install, it is part of the server — <code>get_slow_tests</code> returns the ranked slowest tests, <code>get_performance_trend</code> the duration history, and <code>get_run_insights</code> the worker-imbalance and duration deltas for one run. Useful for &quot;what should I speed up this sprint?&quot; without opening a browser.</p><p><strong>Script it.</strong> The same numbers are on the REST API if you would rather post a weekly CI-cost figure into a channel — see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>.</p><p><strong>Watch it drift.</strong> Rather than auditing periodically, subscribe to the <code>perf.regression</code><a href="./../notifications.html">notification</a> event and let it tell you when a duration trend breaks.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../flaky-tests.html#performance">Flaky tests → Performance</a> — the full reference for trends, slowest tests and timeout hygiene</li><li><a href="./flaky-cleanup.html">Cut the flakiness that costs the most</a> — step 4 in full</li><li><a href="./../analytics.html">Analytics</a> — CI time and wasted CI time across every project</li><li><a href="./../capture-fixtures.html">Capture fixtures</a> — what unlocks the network and Web Vitals views</li></ul>',33)])])}const y=s(n,[["render",l]]);export{w as __pageData,y as default};
